add_action( 'add_meta_boxes', 'perfectpixel_customer_history_metabox' );

function perfectpixel_customer_history_metabox() {
	$screen = function_exists( 'wc_get_page_screen_id' ) ? wc_get_page_screen_id( 'shop-order' ) : 'shop_order';
	add_meta_box( 'perfectpixel_customer_history', 'Ιστορικό πελάτη', 'perfectpixel_customer_history_render', $screen, 'side', 'low' );
}

function perfectpixel_customer_history_render( $post_or_order ) {
	$order = $post_or_order instanceof WC_Order ? $post_or_order : wc_get_order( $post_or_order->ID );
	if ( ! $order ) {
		return;
	}
	$args = array(
		'limit'   => max( 1, (int) '{{customer_history_limit}}' ),
		'exclude' => array( $order->get_id() ),
		'type'    => 'shop_order',
		'orderby' => 'date',
		'order'   => 'DESC',
	);
	if ( $order->get_customer_id() ) {
		$args['customer_id'] = $order->get_customer_id();
	} elseif ( $order->get_billing_email() ) {
		$args['billing_email'] = $order->get_billing_email();
	} else {
		return;
	}
	$orders = wc_get_orders( $args );
	if ( ! $orders ) {
		echo '<p>Δεν υπάρχουν άλλες παραγγελίες από αυτόν τον πελάτη.</p>';
		return;
	}
	echo '<ul style="margin:0">';
	foreach ( $orders as $past ) {
		printf(
			'<li><a href="%s">#%s</a> · %s · %s · %s</li>',
			esc_url( $past->get_edit_order_url() ),
			esc_html( $past->get_order_number() ),
			esc_html( wc_format_datetime( $past->get_date_created() ) ),
			esc_html( wc_get_order_status_name( $past->get_status() ) ),
			wp_kses_post( $past->get_formatted_order_total() )
		);
	}
	echo '</ul>';
}
